package service;
import java.io.*;import java.nio.file.*;import java.nio.file.attribute.BasicFileAttributes;
public class ReportGenerator {public String generate(Path logs,Path report)throws IOException{long deposits=0,withdrawals=0;StringBuilder text=new StringBuilder("MiniBank end-of-day report\n");Files.createDirectories(logs);try(DirectoryStream<Path> stream=Files.newDirectoryStream(logs,"*.log")){for(Path file:stream){for(String line:Files.readAllLines(file)){String[] p=line.trim().split("\\s+");if(p.length>=3)try{long amount=Long.parseLong(p[2]);if(p[0].equals("DEPOSIT"))deposits+=amount;else if(p[0].equals("WITHDRAW"))withdrawals+=amount;}catch(NumberFormatException ignored){}}BasicFileAttributes a=Files.readAttributes(file,BasicFileAttributes.class);text.append(file.getFileName()).append(" size=").append(a.size()).append(" modified=").append(a.lastModifiedTime()).append('\n');}}text.append("Total deposits: ").append(deposits).append("\nTotal withdrawals: ").append(withdrawals).append("\nNet change: ").append(deposits-withdrawals).append('\n');Files.createDirectories(report.toAbsolutePath().getParent());Files.writeString(report,text.toString());return text.toString();}}
